// Sports Medicine Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: special tests, injury mechanisms and evidence-based care.
import {q, mix} from './q.js';
const BEAM='Beam, Orthopedic Taping, Wrapping, Bracing, and Padding', FRA='France, Introduction to Sports Medicine and Athletic Training', PREN='Prentice, The Role of the Athletic Trainer in Sports Medicine';
const PREV='Injury / Illness Prevention and Wellness Promotion', EXAM='Examination, Evaluation, and Assessment', EMER='Immediate and Emergency Care', THER='Therapeutic Intervention', ADMIN='Healthcare Administration and Professional Responsibilities';

export default {
 id:'sports-medicine-1',
 event:'Sports Medicine',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Beam’s Orthopedic Taping, Wrapping, Bracing, and Padding, France’s Introduction to Sports Medicine and Athletic Training, and Prentice’s The Role of the Athletic Trainer',
 plan:[{area:PREV,weight:30},{area:EXAM,weight:30},{area:EMER,weight:16},{area:THER,weight:16},{area:ADMIN,weight:8}],
 questions:mix([
  q(PREV,'What is the main purpose of a preparticipation physical examination?','To screen for risky conditions',['To decide which athletes start in games','To replace yearly medical checkups','To test athletic skill'],'B','The PPE screens for conditions, such as heart problems or previous injuries, that may put an athlete at risk, and provides a baseline for later comparison.',PREN),
  q(PREV,'About how long does it take athletes to acclimatize to exercising in the heat?','10 to 14 days',['1 to 2 days','4 to 6 weeks','3 months'],'D','Gradually increasing practice time and intensity over about 10–14 days improves sweating, plasma volume and heat tolerance.',FRA),
  q(PREV,'Which measurement best reflects heat stress because it accounts for temperature, humidity, wind and sun?','Wet bulb globe temperature',['Air temperature alone','Heat index from a phone app','Dew point only'],'A','WBGT combines several factors that affect the body’s ability to cool itself and is used to modify or cancel practices.',FRA),
  q(PREV,'An athlete loses 2 pounds during practice. About how much fluid should be replaced?','32–48 oz of fluid',['8 oz','16 oz of fluid','80 oz of fluid'],'C','A common guideline is 16–24 oz of fluid for every pound lost, so 2 pounds calls for about 32–48 oz.',FRA),
  q(PREV,'A closed basketweave ankle taping is mainly designed to limit which motion?','Inversion',['Dorsiflexion','Eversion only','Knee flexion'],'B','Most ankle sprains are inversion injuries. Stirrups and horseshoes in the basketweave limit inversion while allowing plantar and dorsiflexion.',BEAM),
  q(PREV,'Which is the main proven benefit of a properly fitted mouthguard?','Preventing dental injuries',['Preventing all concussions','Improving breathing','Reducing neck injuries'],'D','Mouthguards greatly reduce injuries to teeth, lips and jaw. Evidence that they prevent concussion is limited.',FRA),
  q(PREV,'When fitting a football helmet, where should the front edge sit?','About 1 inch above the eyebrows',['Directly on the eyebrows','At the hairline, 3 inches up','Over the bridge of the nose'],'A','The helmet should sit about one finger-width above the eyebrows, fit snugly without shifting, and have the chin strap centered.',FRA),
  q(PREV,'What three conditions make up the female athlete triad?','Low energy, menstrual dysfunction, low bone density',['Anemia, dehydration and frequent muscle cramps','Overtraining, insomnia and depression','Stress fractures, sprains and tendinitis'],'C','Too few calories for training leads to hormonal changes that disrupt menstruation and weaken bones. The broader concept is now called RED-S.',FRA),
  q(PREV,'Which warm-up is generally recommended right before explosive activity?','Dynamic stretching',['Long static stretches','No warm-up at all','Ballistic bouncing stretches'],'B','Dynamic stretching (moving through ranges of motion) raises muscle temperature and prepares the body without reducing power the way long static holds can.',PREN),
  q(PREV,'A runner increases weekly mileage from 15 to 35 miles in two weeks and develops pain over the tibia. Which injury is most likely?','Stress fracture',['Ligament sprain','Muscle contusion','Joint dislocation'],'D','Rapid increases in training load cause repetitive stress that outpaces bone repair. A common guideline is to increase training by no more than about 10% per week.',FRA),
  q(PREV,'Which nutrient is the main fuel for high-intensity exercise?','Carbohydrates',['Protein','Fat','Vitamin C supplements'],'A','Muscle glycogen, from carbohydrate, fuels intense activity. Fat fuels lower-intensity, longer activity, and protein mainly builds and repairs tissue.',FRA),
  q(PREV,'Female endurance athletes are at higher risk for which mineral deficiency?','Iron',['Sodium','Phosphorus','Fluoride'],'C','Menstrual losses, foot-strike hemolysis and diets low in iron can cause iron deficiency, leading to fatigue and reduced performance.',FRA),
  q(PREV,'Which training principle states that muscles must be challenged with gradually greater loads to keep improving?','Overload',['Specificity','Reversibility','Individuality'],'B','Strength and endurance improve when the body is stressed beyond its usual level. Reversibility means fitness is lost when training stops.',PREN),
  q(PREV,'After lightning is seen or thunder is heard, how long should athletes wait after the last strike or thunder before resuming play?','30 minutes',['5 minutes','10 minutes','2 hours'],'D','The 30-minute rule restarts each time lightning is seen or thunder is heard. Athletes should shelter in a building or hard-topped vehicle.',FRA),
  q(PREV,'Which is a known side effect of anabolic steroid use in adolescents?','Early growth plate closure',['Increased height','Lower blood pressure','Improved liver function'],'A','Anabolic steroids can stop bone growth early and cause liver damage, mood changes, acne, heart problems and hormonal changes.',FRA),
  q(EXAM,'What does the HOPS injury evaluation format stand for?','History, Observation, Palpation, Special tests',['Heat, Oxygen, Pressure, Support','Height, Orientation, Pulse, Strength','History, Organization, Plan, Summary'],'C','HOPS guides a systematic evaluation, starting with the athlete’s history and ending with special tests for specific structures.',PREN),
  q(EXAM,'Which special test is most sensitive for an anterior cruciate ligament tear?','Lachman test',['McMurray test','Valgus stress test','Thompson test'],'B','The Lachman test checks anterior translation of the tibia with the knee bent about 20–30 degrees. McMurray tests the meniscus.',FRA),
  q(EXAM,'A blow to the outside of the knee stresses which ligament?','Medial collateral ligament',['Lateral collateral ligament','Posterior cruciate ligament','Patellar tendon'],'D','A force from the outside pushes the knee inward (valgus stress), stretching the MCL on the inside of the knee.',FRA),
  q(EXAM,'Which test is used to check for a meniscus tear?','McMurray test',['Lachman test','Anterior drawer test','Thompson test'],'A','The McMurray test flexes and rotates the knee; a click or pain along the joint line suggests a torn meniscus.',FRA),
  q(EXAM,'Which ankle ligament is most commonly sprained?','Anterior talofibular ligament',['Deltoid ligament','Posterior tibiofibular ligament','Calcaneofibular ligament alone'],'C','The ATFL is the weakest lateral ligament and is first injured in inversion with plantar flexion, the most common ankle sprain mechanism.',FRA),
  q(EXAM,'What are the Ottawa ankle rules used for?','Deciding if an X-ray is needed',['Choosing a taping technique','Grading a concussion','Timing return to play'],'B','The rules check bone tenderness at specific points and the ability to bear weight to decide if a fracture is likely enough to need imaging.',FRA),
  q(EXAM,'Which tool is commonly used on the sideline to evaluate a suspected concussion?','SCAT',['APGAR','Glasgow Coma Scale alone','Braden Scale'],'D','The Sport Concussion Assessment Tool combines symptom scores, cognitive testing, balance testing and neurologic screening.',FRA),
  q(EXAM,'Which rotator cuff muscle does the empty can test assess?','Supraspinatus',['Infraspinatus','Teres minor','Subscapularis'],'A','With the arm raised in the scapular plane and thumb down, weakness or pain resisting downward pressure suggests supraspinatus injury.',FRA),
  q(EXAM,'Squeezing the calf of a prone athlete produces no plantar flexion of the foot. What does this suggest?','An Achilles rupture',['A sprained ankle','A calf contusion','Shin splints in the lower leg'],'C','A positive Thompson test (no foot movement) indicates a complete Achilles tendon rupture.',FRA),
  q(EXAM,'How is a grade III ligament sprain described?','A complete tear with gross instability',['Stretching with no laxity','A partial tear with mild laxity','A bruise of the ligament'],'B','Grade I is a stretch, grade II a partial tear with some laxity, and grade III a complete tear with significant instability.',FRA),
  q(EXAM,'What is the difference between a sprain and a strain?','A sprain injures a ligament; a strain injures a muscle or tendon',['A sprain injures a muscle; a strain injures a bone','A sprain is always more severe','They are the same injury'],'D','Ligaments connect bone to bone (sprains). Muscles and tendons, which connect muscle to bone, are strained.',FRA),
  q(EXAM,'Pain along the inner border of the lower tibia that worsens with running is most consistent with:','Shin splints (MTSS)',['Achilles tendinitis','Plantar fasciitis','Patellar tendinitis'],'A','Commonly called shin splints, it is an overuse injury of the tissues along the medial tibia. Untreated, it can progress to a stress fracture.',FRA),
  q(EXAM,'A young gymnast has low back pain that worsens with back extension. Which injury is common in this sport?','Spondylolysis',['Rotator cuff tear','ACL tear','Ankle sprain'],'C','Repeated hyperextension can cause a stress fracture of the pars interarticularis of a lumbar vertebra.',FRA),
  q(EXAM,'A 13-year-old basketball player has a painful bump just below the kneecap. Which condition is most likely?','Osgood-Schlatter disease',['Meniscus tear','Patellar dislocation','Baker’s cyst'],'B','Osgood-Schlatter is inflammation where the patellar tendon pulls on the tibial tuberosity during adolescent growth spurts.',FRA),
  q(EXAM,'Which instrument measures joint range of motion in degrees?','Goniometer',['Dynamometer','Sphygmomanometer','Skinfold caliper'],'D','A goniometer measures joint angles. A dynamometer measures strength, and calipers measure skinfold thickness.',PREN),
  q(EMER,'What is an emergency action plan?','A rehearsed, written emergency plan',['A list of team practice times','A rehab schedule for injured athletes','A nutrition plan for game days'],'A','EAPs assign roles, list equipment such as AEDs, give venue addresses and access routes, and should be practiced with staff each season.',PREN),
  q(EMER,'A football player is unresponsive on the field after a tackle. What is the first priority?','Stabilize the head; check breathing',['Remove the helmet immediately','Help the athlete sit up','Wait to see if the athlete wakes up'],'C','Assume a spinal injury, manually stabilize the head and assess airway, breathing and circulation. Activate EMS and the emergency action plan.',PREN),
  q(EMER,'For exertional heat stroke, what is the guiding principle when cold-water immersion is available on site?','Cool first, transport second',['Transport first, cool later','Give fluids, then wait','Cover the athlete to prevent shivering'],'B','Rapid cooling in cold water within 30 minutes of collapse gives the best chance of survival. Cooling continues until core temperature drops to about 102 °F (39 °C).',FRA),
  q(EMER,'A baseball strikes a player in the chest, and he collapses without a pulse. What is the likely cause and key treatment?','Commotio cordis; immediate CPR and AED',['A rib fracture; ice the chest','A collapsed lung; give oxygen only','Heat exhaustion; give fluids'],'D','A blow at a vulnerable moment of the heart’s cycle can cause ventricular fibrillation. Survival depends on fast CPR and defibrillation.',FRA),
  q(EMER,'An athlete with known asthma begins wheezing during practice. What should the athletic trainer do first?','Help with the rescue inhaler',['Have the athlete run it off','Give a sports drink','Have the athlete lie flat on the turf'],'A','A short-acting bronchodilator opens the airways. If symptoms do not improve, activate EMS.',FRA),
  q(EMER,'An athlete has an obviously dislocated shoulder. What should the athletic trainer do?','Immobilize it in the position found and refer',['Pull the arm to put it back in place','Have the athlete keep playing','Apply heat and massage'],'C','Without proper training and authorization, the joint is splinted as found and checked for circulation and sensation. Reduction is done by a physician.',FRA),
  q(EMER,'An athlete has an open fracture of the lower leg. What is the correct initial care?','Cover it with a sterile dressing',['Push the bone back under the skin','Wash the bone with tap water','Have the athlete walk to the bench'],'B','Cover the wound to reduce infection, control bleeding, splint as found and activate EMS. Never push bone back in.',FRA),
  q(EMER,'An athlete shows concussion signs during a game but says he feels fine minutes later. What should happen?','He is removed and does not return that day',['He returns if he passes a quick quiz','He returns after 15 minutes of rest','He returns if the coach agrees'],'D','Any athlete suspected of concussion is removed from play and may not return the same day. Return requires medical clearance and a graduated plan.',FRA),
  q(THER,'For an acute ankle sprain, how long is ice usually applied at one time?','About 20 minutes',['About 2 minutes','About 1 hour','Several hours'],'A','Ice is typically applied for about 15–20 minutes, with time to rewarm between sessions, to reduce pain and limit swelling.',FRA),
  q(THER,'Why is heat avoided during the first 48–72 hours after an acute injury?','It increases blood flow and swelling',['It reduces pain too much','It causes the injury to stiffen','It slows healing permanently'],'C','Heat dilates blood vessels, which can increase bleeding and swelling in a fresh injury. Heat is used later for stiffness and chronic conditions.',FRA),
  q(THER,'What is therapeutic ultrasound primarily used for?','Heating deep tissues',['Imaging fractures','Freezing superficial tissue','Measuring muscle strength'],'B','Therapeutic ultrasound uses sound waves to heat tissues several centimeters deep, increasing extensibility and blood flow.',FRA),
  q(THER,'How does TENS help relieve pain?','It blocks pain signals',['It heals ligaments directly','It builds muscle strength','It reduces bone density'],'D','Transcutaneous electrical nerve stimulation activates sensory nerves, which can “close the gate” to pain signals in the spinal cord.',FRA),
  q(THER,'In a typical rehab progression, what is restored before full strength training?','Range of motion',['Sport-specific speed drills','Full-contact practice','Maximum lifting'],'A','Rehab generally progresses from controlling pain and swelling, to restoring range of motion, to strength, then to functional and sport-specific activity.',PREN),
  q(THER,'Which exercise is an example of a closed kinetic chain exercise?','A squat',['A seated leg extension','A biceps curl','A bench fly'],'C','In closed-chain exercises, the foot or hand is fixed against a surface, as in squats and push-ups. These mimic functional movements.',FRA),
  q(THER,'After an ankle sprain, why is a wobble board added to rehab?','To retrain proprioception',['To stretch the hamstrings','To increase heart rate only','To test for a fracture'],'B','Ankle sprains damage joint receptors. Balance training improves proprioception and helps prevent re-injury.',BEAM),
  q(THER,'Which criterion should be met before an athlete returns to full play after a lower-leg injury?','Full motion, strength and function',['The athlete says they feel ready','A full week has passed since the injury','The coach needs the athlete back'],'D','Return-to-play decisions are based on objective criteria, including range of motion, strength, function and medical clearance.',PREN),
  q(ADMIN,'Which organization certifies athletic trainers?','The BOC',['NATA','NCAA','The American Red Cross'],'A','The BOC administers the certification exam that grants the ATC credential. NATA is the national professional association.',PREN),
  q(ADMIN,'Which format is commonly used to document injury evaluations?','SOAP notes',['Lesson plans','Balance sheets','Game statistics'],'C','SOAP stands for Subjective, Objective, Assessment and Plan and creates clear, consistent records.',PREN),
  q(ADMIN,'Athletic trainers practice under the direction of a physician. What document describes the care they may provide?','Standing orders',['A team roster','A practice schedule','An equipment inventory'],'B','Standing orders (or protocols) written by the team physician outline treatments the athletic trainer may provide.',PREN),
  q(ADMIN,'What is the national professional membership association for athletic trainers?','NATA',['BOC','AMA','CAATE'],'D','The National Athletic Trainers’ Association supports athletic trainers through advocacy, education and professional standards.',PREN)
 ],97)
};
